use std::env;
use std::io::{self, Read, Write};
use std::process::ExitCode;

const VERSION: &str = include_str!("resources/version.txt");
const HELP_LONG: &str = include_str!("resources/help_long.txt");
const HELP_SHORT: &str = include_str!("resources/help_short.txt");
const COMPLETION_BASH: &str = include_str!("resources/completion.bash");
const COMPLETION_ZSH: &str = include_str!("resources/completion.zsh");
const COMPLETION_FISH: &str = include_str!("resources/completion.fish");
const COMPLETION_POWERSHELL: &str = include_str!("resources/completion.powershell");
const COMPLETION_ELVISH: &str = include_str!("resources/completion.elvish");
const LIST_LANGUAGES: &str = include_str!("resources/list_languages.txt");
const LIST_SYNTAX_THEMES: &str = include_str!("resources/list_syntax_themes.txt");
const SHOW_SYNTAX_THEMES: &str = include_str!("resources/show_syntax_themes.txt");
const SHOW_COLORS: &str = include_str!("resources/show_colors.txt");
const SHOW_THEMES: &str = include_str!("resources/show_themes.txt");
const SHOW_CONFIG: &str = include_str!("resources/show_config.txt");

fn print_usage_hint(program: &str) {
    eprintln!();
    eprintln!("\x1b[1m\x1b[4mUsage:\x1b[0m \x1b[1m{}\x1b[0m [OPTIONS] [MINUS_FILE] [PLUS_FILE]", program);
    eprintln!();
    eprintln!("For more information, try '\x1b[1m--help\x1b[0m'.");
}

fn error_unexpected_argument(program: &str, arg: &str) -> ExitCode {
    eprintln!("\x1b[1m\x1b[31merror:\x1b[0m unexpected argument '\x1b[33m{}\x1b[0m' found", arg);
    eprintln!();
    eprintln!("  \x1b[32mtip:\x1b[0m to pass '\x1b[33m{}\x1b[0m' as a value, use '\x1b[32m-- {}\x1b[0m'", arg, arg);
    print_usage_hint(program);
    ExitCode::from(2)
}

fn error_missing_value(program: &str, arg: &str) -> ExitCode {
    eprintln!("\x1b[1m\x1b[31merror:\x1b[0m a value is required for '\x1b[1m{}\x1b[0m' but none was supplied", arg);
    print_usage_hint(program);
    ExitCode::from(2)
}

fn error_invalid_value(program: &str, arg: &str, val: &str, possible: &[&str]) -> ExitCode {
    eprintln!("\x1b[1m\x1b[31merror:\x1b[0m invalid value '\x1b[33m{}\x1b[0m' for '\x1b[1m{}\x1b[0m'", val, arg);
    eprintln!("  [possible values: {}]", possible.join(", "));
    print_usage_hint(program);
    ExitCode::from(2)
}

// Options that take a single string value.
const OPTS_WITH_VALUE: &[&str] = &[
    "--blame-code-style",
    "--blame-format",
    "--blame-palette",
    "--blame-separator-format",
    "--blame-separator-style",
    "--blame-timestamp-format",
    "--blame-timestamp-output-format",
    "--config",
    "--commit-decoration-style",
    "--commit-regex",
    "--commit-style",
    "--default-language",
    "--detect-dark-light",
    "--diff-args",
    "-@",
    "--diff-stat-align-width",
    "--features",
    "--file-added-label",
    "--file-copied-label",
    "--file-decoration-style",
    "--file-modified-label",
    "--file-removed-label",
    "--file-renamed-label",
    "--file-style",
    "--file-transformation",
    "--grep-context-line-style",
    "--grep-file-style",
    "--grep-header-decoration-style",
    "--grep-header-file-style",
    "--grep-line-number-style",
    "--grep-output-type",
    "--grep-match-line-style",
    "--grep-match-word-style",
    "--grep-separator-symbol",
    "--hunk-header-decoration-style",
    "--hunk-header-file-style",
    "--hunk-header-line-number-style",
    "--hunk-header-style",
    "--hunk-label",
    "--hyperlinks-commit-link-format",
    "--hyperlinks-file-link-format",
    "--inline-hint-style",
    "--inspect-raw-lines",
    "--line-buffer-size",
    "--line-fill-method",
    "--line-numbers-left-format",
    "--line-numbers-left-style",
    "--line-numbers-minus-style",
    "--line-numbers-plus-style",
    "--line-numbers-right-format",
    "--line-numbers-right-style",
    "--line-numbers-zero-style",
    "--map-styles",
    "--max-line-distance",
    "--max-syntax-highlighting-length",
    "--max-line-length",
    "--merge-conflict-begin-symbol",
    "--merge-conflict-end-symbol",
    "--merge-conflict-ours-diff-header-decoration-style",
    "--merge-conflict-ours-diff-header-style",
    "--merge-conflict-theirs-diff-header-decoration-style",
    "--merge-conflict-theirs-diff-header-style",
    "--minus-empty-line-marker-style",
    "--minus-emph-style",
    "--minus-non-emph-style",
    "--minus-style",
    "--navigate-regex",
    "--pager",
    "--paging",
    "--parse-ansi",
    "--plus-emph-style",
    "--plus-empty-line-marker-style",
    "--plus-non-emph-style",
    "--plus-style",
    "--right-arrow",
    "--syntax-theme",
    "--tabs",
    "--true-color",
    "--whitespace-error-style",
    "--width",
    "--word-diff-regex",
    "--wrap-left-symbol",
    "--wrap-max-lines",
    "--wrap-right-percent",
    "--wrap-right-prefix-symbol",
    "--wrap-right-symbol",
    "--zero-style",
    "--24-bit-color",
    "-n",
    "-w",
];

// Boolean flags (no argument).
const FLAGS: &[&str] = &[
    "--color-only",
    "--dark",
    "--diff-highlight",
    "--diff-so-fancy",
    "--hyperlinks",
    "--keep-plus-minus-markers",
    "--light",
    "--line-numbers",
    "--navigate",
    "--no-gitconfig",
    "--raw",
    "--relative-paths",
    "--side-by-side",
    "-s",
];

fn stdin_passthrough() -> io::Result<()> {
    let mut buf = Vec::new();
    io::stdin().lock().read_to_end(&mut buf)?;
    let stdout = io::stdout();
    let mut stdout = stdout.lock();
    stdout.write_all(&buf)?;
    stdout.flush()?;
    Ok(())
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    let program = args.get(0).cloned().unwrap_or_else(|| "delta".to_string());

    let mut i = 1;
    let mut positional: Vec<String> = Vec::new();

    while i < args.len() {
        let a = args[i].as_str();

        if a == "--" {
            for x in &args[i+1..] {
                positional.push(x.clone());
            }
            break;
        }

        if a == "--version" || a == "-V" {
            print!("{}", VERSION);
            return ExitCode::SUCCESS;
        }
        if a == "--help" {
            print!("{}", HELP_LONG);
            return ExitCode::SUCCESS;
        }
        if a == "-h" {
            print!("{}", HELP_SHORT);
            return ExitCode::SUCCESS;
        }

        if a == "--list-languages" {
            print!("{}", LIST_LANGUAGES);
            return ExitCode::SUCCESS;
        }
        if a == "--list-syntax-themes" {
            print!("{}", LIST_SYNTAX_THEMES);
            return ExitCode::SUCCESS;
        }
        if a == "--show-syntax-themes" {
            print!("{}", SHOW_SYNTAX_THEMES);
            return ExitCode::SUCCESS;
        }
        if a == "--show-colors" {
            print!("{}", SHOW_COLORS);
            return ExitCode::SUCCESS;
        }
        if a == "--show-themes" {
            print!("{}", SHOW_THEMES);
            return ExitCode::SUCCESS;
        }
        if a == "--show-config" {
            print!("{}", SHOW_CONFIG);
            return ExitCode::SUCCESS;
        }

        if a == "--generate-completion" {
            if i + 1 >= args.len() {
                return error_missing_value(&program, a);
            }
            let v = &args[i + 1];
            let out = match v.as_str() {
                "bash" => COMPLETION_BASH,
                "zsh" => COMPLETION_ZSH,
                "fish" => COMPLETION_FISH,
                "powershell" => COMPLETION_POWERSHELL,
                "elvish" => COMPLETION_ELVISH,
                _ => return error_invalid_value(&program, a, v, &["bash", "elvish", "fish", "powershell", "zsh"]),
            };
            print!("{}", out);
            return ExitCode::SUCCESS;
        }

        // Attached value form: --opt=value
        if let Some(eq) = a.find('=') {
            let (key, _val) = a.split_at(eq);
            if OPTS_WITH_VALUE.contains(&key) {
                i += 1;
                continue;
            }
        }

        if OPTS_WITH_VALUE.contains(&a) {
            if i + 1 >= args.len() {
                return error_missing_value(&program, a);
            }
            i += 2;
            continue;
        }

        if FLAGS.contains(&a) {
            i += 1;
            continue;
        }

        if a.starts_with("--") || (a.starts_with('-') && a.len() > 1 && !a.starts_with("-@")) {
            // Positional values sometimes look like "-" (stdin). Allow "-".
            if a == "-" {
                positional.push(a.to_string());
                i += 1;
                continue;
            }
            return error_unexpected_argument(&program, a);
        }

        positional.push(a.to_string());
        i += 1;
    }

    // If no positional files were given, read stdin and pass through.
    if positional.is_empty() {
        if let Err(e) = stdin_passthrough() {
            eprintln!("delta: {}", e);
            return ExitCode::from(1);
        }
        return ExitCode::SUCCESS;
    }

    // Two-file diff: try using `diff -u` as a fallback.
    if positional.len() >= 2 {
        use std::process::Command;
        let out = Command::new("diff")
            .arg("-u")
            .arg(&positional[0])
            .arg(&positional[1])
            .output();
        match out {
            Ok(o) => {
                io::stdout().write_all(&o.stdout).ok();
                io::stderr().write_all(&o.stderr).ok();
                return ExitCode::SUCCESS;
            }
            Err(_) => return ExitCode::from(1),
        }
    }

    ExitCode::SUCCESS
}
EOF
